// Combine the requirement task details with existing test coverage into one clean context object for Claude.
const cfg = $('Set - Config').first().json;
const all = $input.first().json;

const requirementTask = all.requirement || all[0] || {};
const existingCoverage = all.existingTests || all[1] || {};

const existingTasks = existingCoverage.tasks || (Array.isArray(existingCoverage) ? existingCoverage : []);

const existingScenarioSummaries = existingTasks.map(t => ({
  name: t.name,
  status: t.status?.status,
  platform: (t.tags || []).map(tag => tag.name).find(n => ['ios', 'android', 'both'].includes((n || '').toLowerCase())) || 'unspecified'
}));

return [{
  json: {
    ...cfg,
    requirementTitle: requirementTask.name || 'Untitled requirement',
    requirementDescription: requirementTask.text_content || requirementTask.description || '',
    requirementCustomFields: requirementTask.custom_fields || [],
    requirementId: requirementTask.id || cfg.requirementTaskId,
    existingScenarioSummaries
  }
}];

const cfg = $('JS - Build Requirement Context').first().json;
const response = $input.first().json;

const textBlock = (response.content || []).find(b => b.type === 'text');
let parsed = { scenarios: [] };
try {
  const raw = (textBlock?.text || '{}').replace(/```json|```/g, '').trim();
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = { scenarios: [], parseError: true };
}

const scenarios = parsed.scenarios || [];
if (scenarios.length === 0) {
  return [{ json: { ...cfg, noScenarios: true } }];
}

return scenarios.map(s => ({
  json: {
    clickupTestingListId: cfg.clickupTestingListId,
    requirementId: cfg.requirementId,
    requirementTitle: cfg.requirementTitle,
    ...s,
    noScenarios: false
  }
}));

const scenario = $('JS - Parse Test Scenarios').first().json;
const task = $input.first().json;

return [{
  json: {
    ...scenario,
    testingTaskId: task.id,
    testingTaskUrl: task.url
  }
}];

// Summarize pass/fail/blocked counts across all testing tasks for this requirement,
// and build the executed scenario list for the gap-analysis prompt.
const ctx = $('JS - Attach Task Id to Scenario Record').first().json;
const response = $input.first().json;
const tasks = response.tasks || (Array.isArray(response) ? response : []);

function normalizeStatus(s) {
  const v = (s || '').toLowerCase();
  if (v.includes('pass')) return 'passed';
  if (v.includes('fail')) return 'failed';
  if (v.includes('block')) return 'blocked';
  return 'pending';
}

const executedScenarios = tasks.map(t => ({
  title: t.name,
  status: normalizeStatus(t.status?.status),
  platform: (t.tags || []).map(tag => tag.name).find(n => ['ios', 'android', 'both'].includes((n || '').toLowerCase())) || 'unspecified'
}));

const summary = executedScenarios.reduce((acc, s) => {
  acc[s.status] = (acc[s.status] || 0) + 1;
  return acc;
}, {});

return [{
  json: {
    ...ctx,
    executedScenarios,
    resultsSummary: summary,
    totalTestingTasks: tasks.length
  }
}];

const ctx = $('JS - Aggregate Results').first().json;
const response = $input.first().json;

const textBlock = (response.content || []).find(b => b.type === 'text');
let parsed = { hasGaps: false, missingScenarios: [] };
try {
  const raw = (textBlock?.text || '{}').replace(/```json|```/g, '').trim();
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = { hasGaps: false, missingScenarios: [], parseError: true };
}

return [{
  json: {
    ...ctx,
    hasGaps: parsed.hasGaps === true,
    missingScenarios: parsed.missingScenarios || []
  }
}];

